// go: github.com/microsoft/TypeScript/tsc/internal/outputpaths.computeCommonSourceDirectoryOfFilenames ea698899
fun computeCommonSourceDirectoryOfFilenames(fileNames: GoSlice<RootedFilePath>, currentDirectory: RootedDirectoryPath, caseSensitivity: CaseSensitivity): RootedDirectoryPath {
    if (fileNames.len == 0) {
        return currentDirectory
    }
    return caseSensitivity.commonDirectoryOfFiles(fileNames)
}

// go: github.com/microsoft/TypeScript/tsc/internal/outputpaths.GetComputedCommonSourceDirectory 89aa0415
fun getComputedCommonSourceDirectory(emittedFiles: GoSlice<RootedFilePath>, currentDirectory: RootedDirectoryPath, caseSensitivity: CaseSensitivity): RootedDirectoryPath {
    return computeCommonSourceDirectoryOfFilenames(emittedFiles, currentDirectory, caseSensitivity)
}

// go: github.com/microsoft/TypeScript/tsc/internal/outputpaths.GetCommonSourceDirectory c3f656b8
fun getCommonSourceDirectory(options: CompilerOptions?, files: (() -> GoSlice<RootedFilePath>)?, currentDirectory: RootedDirectoryPath, caseSensitivity: CaseSensitivity, checkSourceFilesBelongToPath: ((GoSlice<RootedFilePath>, RootedDirectoryPath) -> Boolean)?): RootedDirectoryPath {
    var commonSourceDirectory: RootedDirectoryPath = RootedDirectoryPath("")
    if (options!!.rootDir.value != "") {
        commonSourceDirectory = options!!.rootDir
        if (checkSourceFilesBelongToPath != null) {
            checkSourceFilesBelongToPath!!(files!!(), commonSourceDirectory)
        }
    } else if (options!!.configFilePath.value != "") {
        commonSourceDirectory = options!!.configFilePath.directory()
        if (checkSourceFilesBelongToPath != null) {
            checkSourceFilesBelongToPath!!(files!!(), commonSourceDirectory)
        }
    } else {
